import java.sql.*;
import javax.servlet.http.*;

public class UserLoginSecure {
    public boolean authenticate(HttpServletRequest request, Connection conn) throws SQLException {
        // Getting user input directly from the request
        String username = request.getParameter("username");
        String password = request.getParameter("password");

        // SAFE: Using a parameterized query with placeholders (?) instead of string concatenation
        // This ensures user input is always treated as data, never as executable SQL
        String query = "SELECT * FROM users WHERE username = ? AND password = ?";

        // Using try-with-resources to ensure proper cleanup of database resources
        // PreparedStatement automatically escapes and safely binds parameters
        try (PreparedStatement pstmt = conn.prepareStatement(query)) {
            // Bind parameters safely — the API handles escaping and type safety
            pstmt.setString(1, username);
            pstmt.setString(2, password);

            // Execute the safely parameterized query
            try (ResultSet rs = pstmt.executeQuery()) {
                // Check if a matching user was found
                boolean authenticated = rs.next();
                return authenticated;
            }
        }
        // Resources are automatically closed by try-with-resources, preventing leaks
    }
}
